// Integration tests for nightly-barter-calculator\n// These tests run the binary as a subprocess and verify output.\n\nuse std::process::Command;\n\n#[test]\nfn cli_returns_correct_total() {\n    // Mock rationale: deterministic CLI invocation with known arguments\n    let output = Command::new("../target/debug/nightly-barter-calculator")\n        .args(&["water:1", "fuel:2"])\n        .output()\n        .expect("failed to execute process");\n    let stdout = String::from_utf8_lossy(&output.stdout);\n    // water: 5.0 * 1.2 * 1 = 6.0\n    // fuel: 15.0 * 1.8 * 2 = 54.0\n    // total = 60.0\n    assert!(stdout.contains("Total barter value: 60"));\n}\n\n#[test]\nfn cli_errors_on_unknown_item() {\n    // Mock rationale: ensure the binary exits with non‑zero status for bad input\n    let status = Command::new("../target/debug/nightly-barter-calculator")\n        .arg("unknown:1")\n        .status()\n        .expect("failed to execute process");\n    assert!(!status.success());\n}\n
